<?php
use PHPUnit\Framework\TestCase;
use ServSys\Users\Capabilities;
final class Phase9ServiceCallChargesTest extends TestCase {
 public function test_charge_schema_is_versioned_and_snapshot_complete(): void {$boot=file_get_contents(__DIR__.'/../../servsys.php');$schema=file_get_contents(__DIR__.'/../../src/Database/Schema.php');$this->assertStringContainsString("SERVSYS_DB_VERSION', 16",$boot);$this->assertStringContainsString('servsys_service_call_charges',$schema);foreach(array('company_id','service_call_id','source_type','flat_rate_item_id','flat_rate_code_snapshot','description_snapshot','customer_notes_snapshot','price_type_snapshot','quantity','labor_hours_snapshot','labor_rate_snapshot','material_cost_snapshot','part_markup_multiplier_snapshot','material_selling_total_snapshot','sales_tax_percent_snapshot','sales_tax_snapshot','base_price_snapshot','price_multiplier_snapshot','unit_price_snapshot','extended_price','no_discount_snapshot','special_item_snapshot') as $column){$this->assertStringContainsString($column,$schema);}}
 public function test_charge_repository_is_company_scoped_and_has_authoritative_charge_total(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallChargeRepository.php');$this->assertStringContainsString('company_id=%d',$p);$this->assertStringContainsString('SUM(extended_price)',$p);$this->assertStringContainsString("CompanyContext::current_company_id()",$p);}
 public function test_flat_rate_charge_snapshots_price_book_and_pricing_inputs(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallChargeService.php');foreach(array("'source_type'=>'flat_rate'","'flat_rate_code_snapshot'=>(int)\$item['code']","'description_snapshot'=>\$item['description']","'labor_hours_snapshot'=>(float)\$item['labor_hours']","'labor_rate_snapshot'=>(float)\$config['labor_rate']","'material_cost_snapshot'=>\$pricing['material_cost']","'sales_tax_snapshot'=>\$pricing['sales_tax']","'unit_price_snapshot'=>\$pricing['price']","'no_discount_snapshot'=>!empty(\$item['no_discount'])","'special_item_snapshot'=>!empty(\$item['special_item'])") as $needle){$this->assertStringContainsString($needle,$p);}}
 public function test_flat_rate_recipe_prices_charge_without_consuming_inventory(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallChargeService.php');$this->assertStringContainsString("['unit_cost']",$p);$this->assertStringContainsString('FlatRatePricingEngine::calculate',$p);$this->assertStringNotContainsString('consume_for_service_call',$p);$this->assertStringNotContainsString('InventoryService',$p);}
 public function test_manual_charge_is_authorized_snapshot_not_flat_rate_provenance(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallChargeService.php');$this->assertStringContainsString("'source_type'=>'manual'",$p);$this->assertStringContainsString("'flat_rate_item_id'=>null",$p);$this->assertStringContainsString("'flat_rate_code_snapshot'=>null",$p);$this->assertStringContainsString("'extended_price'=>round(\$unit_price*\$quantity,4)",$p);}
 public function test_cross_company_and_inactive_flat_rate_items_are_rejected(): void {$p=file_get_contents(__DIR__.'/../../src/ServiceCalls/ServiceCallChargeService.php');$this->assertStringContainsString("Flat Rate item does not belong to this Service Call company.",$p);$this->assertStringContainsString("Inactive Flat Rate items cannot be added to a Service Call.",$p);$this->assertStringContainsString("Service Call does not belong to the current company.",$p);}
 public function test_charge_permissions_are_company_permissions(): void {$this->assertContains(Capabilities::VIEW_SERVICE_CALL_CHARGES,Capabilities::company_capabilities());$this->assertContains(Capabilities::MANAGE_SERVICE_CALL_CHARGES,Capabilities::company_capabilities());$this->assertContains(Capabilities::VIEW_SERVICE_CALL_CHARGES,Capabilities::all());$this->assertContains(Capabilities::MANAGE_SERVICE_CALL_CHARGES,Capabilities::all());}
 public function test_workspace_explains_snapshot_and_inventory_separation(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/ServiceCallChargesPage.php');$this->assertStringContainsString('Charge prices are snapshots',$p);$this->assertStringContainsString('Inventory usage is recorded separately',$p);$this->assertStringContainsString('Add Flat Rate Charge',$p);$this->assertStringContainsString('Add Manual Charge',$p);}
 public function test_installer_upgrade_path_uses_schema_dbdelta(): void {$p=file_get_contents(__DIR__.'/../../src/Database/Installer.php');$this->assertStringContainsString('if ( $installed < SERVSYS_DB_VERSION )',$p);$this->assertStringContainsString('foreach ( Schema::tables( $wpdb ) as $sql )',$p);$this->assertStringContainsString('dbDelta( $sql )',$p);}
}
